namespace Nro.Tests.Unit.Game;

/// <summary>
/// Compares the C# game-model classes of track D with values produced by the REAL JDK: <c>game-model-differential.json</c> next to this file, generated by
/// <c>GameModelGenerator.java.txt</c> (the sections "skillCopy", "skillDamage" and "intrinsic" run the original, unchanged Java classes; the other sections run
/// the original method bodies copied into the generator, see its header). Each test walks one section and fails on the first mismatches with the input in the message.
/// </summary>
public class GameModelDifferentialTests
{
    private const int MaxReportedFailures = 20;

    private static readonly Lazy<JsonDocument> Corpus = new(() => JsonDocument.Parse(File.ReadAllBytes(Path.Combine(TestPaths.ProjectDirectory("Nro.Tests.Unit"), "Game", "game-model-differential.json"))));

    private static JsonElement Section(string name) => Corpus.Value.RootElement.GetProperty(name);

    private static long L(JsonElement e) => e.GetInt64();

    private static int I(JsonElement e) => e.GetInt32();

    private static void AssertNoFailures(string section, List<string> failures, int total)
    {
        Assert.True(total > 0, section + ": the section is empty");
        Assert.True(failures.Count == 0, $"{section}: {failures.Count} of {total} cases differ from Java:\n" + string.Join("\n", failures.Take(MaxReportedFailures)));
    }

    [Fact]
    public void Skill_copy_constructor_matches_the_real_java_class()
    {
        var failures = new List<string>();
        int total = 0;
        foreach (JsonElement row in Section("skillCopy").EnumerateArray())
        {
            total++;
            JsonElement input = row[0];
            JsonElement expected = row[1];
            var template = new SkillTemplate { Id = unchecked((sbyte)I(input[14])) };
            var original = new Skill
            {
                Template = template,
                SkillId = (short)I(input[0]),
                Point = I(input[1]),
                PowRequire = L(input[2]),
                CoolDown = I(input[3]),
                LastTimeUseThisSkill = L(input[4]),
                Dx = I(input[5]),
                Dy = I(input[6]),
                MaxFight = I(input[7]),
                ManaUse = I(input[8]),
                Damage = (short)I(input[9]),
                CurrLevel = (short)I(input[10]),
                LastTimeUseThisSkillbot = L(input[11]),
                Price = (short)I(input[12]),
                MoreInfo = input[13].ValueKind == JsonValueKind.Null ? null : input[13].GetString(),
            };

            var copy = new Skill(original);
            object?[] actual =
            [
                copy.SkillId, copy.Point, copy.PowRequire, copy.CoolDown, copy.LastTimeUseThisSkill, copy.Dx, copy.Dy, copy.MaxFight, copy.ManaUse,
                copy.Damage, copy.CurrLevel, copy.LastTimeUseThisSkillbot, copy.Price, copy.MoreInfo, ReferenceEquals(copy.Template, template),
            ];
            for (int i = 0; i < actual.Length; i++)
            {
                JsonElement want = expected[i];
                bool same = want.ValueKind switch
                {
                    JsonValueKind.Null => actual[i] is null,
                    JsonValueKind.String => (string?)actual[i] == want.GetString(),
                    JsonValueKind.True => actual[i] is true,
                    JsonValueKind.False => actual[i] is false,
                    _ => Convert.ToInt64(actual[i], CultureInfo.InvariantCulture) == want.GetInt64(),
                };
                if (!same)
                {
                    failures.Add($"row {total} field {i}: C# {actual[i]} Java {want}");
                }
            }
        }

        AssertNoFailures("skillCopy", failures, total);
    }

    [Fact]
    public void Skill_damage_multipliers_match_the_real_java_class_before_and_after_changes()
    {
        JsonElement section = Section("skillDamage");
        var config = new SkillDamageConfig();
        var failures = new List<string>();
        int total = 0;
        foreach (var (name, changes) in new[] { ("initial", false), ("afterSet", true) })
        {
            if (changes)
            {
                config.SetMultiplier(1, 5.5);
                config.SetMultiplier(100, 0.25);
                config.SetMultiplier(-7, -2.0);
                config.SetMultiplier(Skill.DRAGON, 0.0);
            }

            JsonElement expected = section.GetProperty(name);
            Assert.Equal(256, expected.GetArrayLength());
            for (int id = -128; id <= 127; id++)
            {
                total++;
                double java = double.Parse(expected[id + 128].GetRawText(), CultureInfo.InvariantCulture);
                double csharp = config.GetMultiplier(unchecked((sbyte)id));
                if (BitConverter.DoubleToInt64Bits(java) != BitConverter.DoubleToInt64Bits(csharp))
                {
                    failures.Add($"{name} skill {id}: C# {csharp:R} Java {java:R}");
                }
            }
        }

        AssertNoFailures("skillDamage", failures, total);
    }

    [Fact]
    public void Player_skill_index_matches_java_for_every_skill_id()
    {
        JsonElement expected = Section("skillIndex");
        Assert.Equal(256, expected.GetArrayLength());
        var failures = new List<string>();
        for (int id = -128; id <= 127; id++)
        {
            var player = new Player();
            player.PlayerSkill.SkillSelect = new Skill { Template = new SkillTemplate { Id = unchecked((sbyte)id) } };
            int actual = player.PlayerSkill.GetIndexSkillSelect();
            if (actual != I(expected[id + 128]))
            {
                failures.Add($"skill {id}: C# {actual} Java {expected[id + 128]}");
            }
        }

        AssertNoFailures("skillIndex", failures, 256);
    }

