    [Fact]
    public void Side_event_and_kol_task_texts_and_percentages_match_java()
    {
        var failures = new List<string>();
        int total = 0;
        foreach (JsonElement row in Section("taskText").EnumerateArray())
        {
            total++;
            switch (row[0].GetString())
            {
                case "name":
                    {
                        string template = row[1].GetString()!;
                        int maxCount = I(row[2]);
                        var side = new SideTask { Template = new SideTaskTemplate(1, template, ValidRanges()), MaxCount = maxCount };
                        var evt = new EventTask { Template = new EventTaskTemplate(1, template, ValidRanges()), MaxCount = maxCount };
                        string java = row[3].GetString()!;
                        if (side.GetName() != java || evt.GetName() != java)
                        {
                            failures.Add($"name '{template}' {maxCount}: C# '{side.GetName()}'/'{evt.GetName()}' Java '{java}'");
                        }

                        break;
                    }

                case "level":
                    {
                        string java = row[2].GetString()!;
                        var side = new SideTask { Level = I(row[1]) };
                        var evt = new EventTask { Level = I(row[1]) };
                        if (side.GetLevel() != java || evt.GetLevel() != java)
                        {
                            failures.Add($"level {row[1]}: C# '{side.GetLevel()}'/'{evt.GetLevel()}' Java '{java}'");
                        }

                        break;
                    }

                case "percent":
                    {
                        int count = I(row[1]);
                        int maxCount = I(row[2]);
                        string javaSide = row[3].GetString()!;
                        string javaKol = row[4].GetString()!;
                        string sideResult = Run(() => new SideTask { Count = count, MaxCount = maxCount }.GetPercentProcess());
                        string eventResult = Run(() => new EventTask { Count = count, MaxCount = maxCount }.GetPercentProcess());
                        var kol = new KolTask { Template = new KolTaskTemplate(5, "x", maxCount, new FakeKolItems()), Count = count };
                        string kolResult = Run(() => kol.GetPercentProcess());
                        if (sideResult != javaSide || eventResult != javaSide || kolResult != javaKol)
                        {
                            failures.Add($"percent count {count} max {maxCount}: C# side {sideResult} event {eventResult} kol {kolResult} Java side {javaSide} kol {javaKol}");
                        }

                        break;
                    }

                case "kolInfo":
                    {
                        var kol = new KolTask { Template = new KolTaskTemplate(5, row[1].GetString()!, I(row[2]), new FakeKolItems()) };
                        if (kol.GetTaskInfo() != row[3].GetString())
                        {
                            failures.Add($"kolInfo '{row[1]}' {row[2]}: C# '{kol.GetTaskInfo()}' Java '{row[3]}'");
                        }

                        break;
                    }

                default:
                    failures.Add("unknown row kind " + row[0]);
                    break;
            }
        }

        AssertNoFailures("taskText", failures, total);

        static string Run(Func<int> action)
        {
            try
            {
                return action().ToString(CultureInfo.InvariantCulture);
            }
            catch (DivideByZeroException)
            {
                return "ArithmeticException";
            }
        }
    }

    [Fact]
    public async Task Task_range_parsing_accepts_and_rejects_the_same_texts_as_java()
    {
        var failures = new List<string>();
        int total = 0;
        foreach (JsonElement row in Section("taskRange").EnumerateArray())
        {
            total++;
            string text = row[0].GetString()!;
            JsonElement java = row[1];
            var db = new FakeSqlExecutor()
                .Table("from task_main_template", TaskCatalogTests.MainColumns)
                .Table("from side_task_template", TaskCatalogTests.SideColumns, new object?[] { 1, "side", text, "1-2", "3-4", "5-6", "7-8" })
                .Table("from task_kol_template", TaskCatalogTests.KolColumns)
                .Table("from task_event_template", TaskCatalogTests.SideColumns);
            var catalog = new TaskCatalog();
            bool csharpOk;
            try
            {
                await catalog.LoadAsync(db, new FakeKolItems());
                csharpOk = true;
            }
            catch (InvalidDataException)
            {
                csharpOk = false;
            }

            bool javaOk = java[0].GetString() == "ok";
            if (csharpOk != javaOk)
            {
                failures.Add($"'{text}': C# ok={csharpOk} Java {java}");
            }
            else if (javaOk && (catalog.SideTaskTemplates[0].Count[0][0] != I(java[1]) || catalog.SideTaskTemplates[0].Count[0][1] != I(java[2])))
            {
                failures.Add($"'{text}': C# ({catalog.SideTaskTemplates[0].Count[0][0]},{catalog.SideTaskTemplates[0].Count[0][1]}) Java {java}");
            }
        }

        AssertNoFailures("taskRange", failures, total);
    }

