        {
            total++;
            var it = new Intrinsic
            {
                Id = I(row[0]),
                Name = row[1].GetString()!,
                ParamFrom1 = (short)I(row[2]),
                ParamTo1 = (short)I(row[3]),
                ParamFrom2 = (short)I(row[4]),
                ParamTo2 = (short)I(row[5]),
                Param1 = (short)I(row[6]),
                Param2 = (short)I(row[7]),
                Icon = 1234,
                Gender = 0,
            };
            var copy = new Intrinsic(it);
            if (it.GetDescription() != row[8].GetString() || it.GetName() != row[9].GetString() || copy.Param1 != I(row[10]) || copy.Param2 != I(row[11]) || copy.GetName() != row[12].GetString() || copy.Icon != I(row[13]))
            {
                failures.Add($"id {row[0]} name '{row[1]}' params {row[2]},{row[3]},{row[4]},{row[5]},{row[6]},{row[7]}: C# '{it.GetDescription()}' | '{it.GetName()}' | '{copy.GetName()}' Java '{row[8]}' | '{row[9]}' | '{row[12]}'");
            }
